-- 3 Nov 2026 (Amit: "yes" to claude/guide-text-pass-2026-11-03 in the Project): lesson guide text pass.
-- Each change replaces exact current text only, so a step already edited by hand is left alone. Applied to the live database on 3 Nov 2026.
begin;
update lesson_guides set data = jsonb_set(data, '{steps,1,d}', to_jsonb(replace(data #>> '{steps,1,d}', 'Everything in this course happens there until Day 13, so you can''t lose a penny while you learn.', 'Everything starts there, so you can''t lose a penny while you learn. Moving to real money later is your choice (Lesson 13).'))) where id = 'qs-2' and strpos(data #>> '{steps,1,d}', 'Everything in this course happens there until Day 13, so you can''t lose a penny while you learn.') > 0;
update lesson_guides set data = jsonb_set(data, '{steps,0,d}', to_jsonb(replace(data #>> '{steps,0,d}', 'The free plan is plenty: the robot sends about two emails a day.', 'The free plan is plenty: the robot sends one email a day (or one a week if you choose), plus anything that needs you.'))) where id = 'qs-3' and strpos(data #>> '{steps,0,d}', 'The free plan is plenty: the robot sends about two emails a day.') > 0;
update lesson_guides set data = jsonb_set(data, '{steps,2,d}', to_jsonb(replace(data #>> '{steps,2,d}', 'Actions → Weekly signals → Run workflow. Open the email. This time read it before you approve:', 'It runs itself on Sunday at 7pm. When the email arrives, read it before you approve:'))) where id = 'day-2' and strpos(data #>> '{steps,2,d}', 'Actions → Weekly signals → Run workflow. Open the email. This time read it before you approve:') > 0;
update lesson_guides set data = jsonb_set(data, '{steps,1,d}', to_jsonb(replace(data #>> '{steps,1,d}', 'Read the three bundles (cautious, balanced, adventurous) in universe.json and choose.', 'Pick Balanced or Adventurous in Set up my robot → Your choices.'))) where id = 'day-4' and strpos(data #>> '{steps,1,d}', 'Read the three bundles (cautious, balanced, adventurous) in universe.json and choose.') > 0;
update lesson_guides set data = jsonb_set(data, '{tips,0}', to_jsonb(replace(data #>> '{tips,0}', '(QuickStart 6)', '(QuickStart 5)'))) where id = 'day-6' and strpos(data #>> '{tips,0}', '(QuickStart 6)') > 0;
update lesson_guides set data = jsonb_set(data, '{tips,1}', to_jsonb(replace(data #>> '{tips,1}', 'Four clean practice weeks is the floor, not the ceiling.', 'We suggest four weekly plans, including a month end, before real money. A suggestion, not a rule.'))) where id = 'day-6' and strpos(data #>> '{tips,1}', 'Four clean practice weeks is the floor, not the ceiling.') > 0;
update lesson_guides set data = jsonb_set(data, '{steps,0,d}', to_jsonb(replace(data #>> '{steps,0,d}', 'The five keys your robot holds,', 'The keys your robot holds,'))) where id = 'day-10' and strpos(data #>> '{steps,0,d}', 'The five keys your robot holds,') > 0;
update lesson_guides set data = jsonb_set(data, '{tips,0}', to_jsonb(replace(data #>> '{tips,0}', 'Five keys: broker (robot), broker (dashboard, read only), Resend, Sentry, Claude.', 'Your keys: Trading 212 (robot), Trading 212 read-only, Cloudflare and the GitHub approve token (all three for Robot Dash), and Resend. Optional: Claude, for Claude fixes.'))) where id = 'day-10' and strpos(data #>> '{tips,0}', 'Five keys: broker (robot), broker (dashboard, read only), Resend, Sentry, Claude.') > 0;
update lesson_guides set data = jsonb_set(data, '{steps,2,d}', to_jsonb(replace(data #>> '{steps,2,d}', 'rejected or halt in the subject', 'refused or paused in the subject'))) where id = 'day-11' and strpos(data #>> '{steps,2,d}', 'rejected or halt in the subject') > 0;
update lesson_guides set data = jsonb_set(data, '{tips,0}', to_jsonb(replace(data #>> '{tips,0}', '(QuickStart 6)', '(QuickStart 5)'))) where id = 'day-11' and strpos(data #>> '{tips,0}', '(QuickStart 6)') > 0;
update lesson_guides set data = jsonb_set(data, '{steps,1,d}', to_jsonb(replace(data #>> '{steps,1,d}', 'Run ops/golive.py, or ask Claude to run it, and read the five lines. Fail or skipped is a to-do list, not a verdict.', 'In Switch to real money, press Run the go-live check and read the five lines. Not ticked or skipped is a to-do list, not a verdict.'))) where id = 'day-13' and strpos(data #>> '{steps,1,d}', 'Run ops/golive.py, or ask Claude to run it, and read the five lines. Fail or skipped is a to-do list, not a verdict.') > 0;
update lesson_guides set data = jsonb_set(data, '{steps,2,t}', to_jsonb(replace(data #>> '{steps,2,t}', 'All pass? Wait a week anyway', 'Your choice, any week'))) where id = 'day-13' and strpos(data #>> '{steps,2,t}', 'All pass? Wait a week anyway') > 0;
update lesson_guides set data = jsonb_set(data, '{steps,2,d}', to_jsonb(replace(data #>> '{steps,2,d}', 'The go-live check doesn''t expire. If and when you choose to go live: a live key with the same scopes, the same two secrets, T212_ENV set to live, and smaller than you think.', 'The go-live check is advice, not a gate, and it doesn''t expire. If and when you choose to go live, Switch to real money takes your live key and does the rest. Start smaller than you think.'))) where id = 'day-13' and strpos(data #>> '{steps,2,d}', 'The go-live check doesn''t expire. If and when you choose to go live: a live key with the same scopes, the same two secrets, T212_ENV set to live, and smaller than you think.') > 0;
update lesson_guides set data = jsonb_set(data, '{tips,0}', to_jsonb(replace(data #>> '{tips,0}', 'The go-live check reads your own records; it can''t be argued with, only passed.', 'The go-live check reads your own records and shows what''s ticked. Switching is still your decision.'))) where id = 'day-13' and strpos(data #>> '{tips,0}', 'The go-live check reads your own records; it can''t be argued with, only passed.') > 0;
update lesson_guides set data = jsonb_set(data, '{tips,2}', to_jsonb(replace(data #>> '{tips,2}', 'Live key: same boxes ticked, the same two secrets, T212_ENV set to live.', 'Live key: tick the same boxes as your practice key. Switch to real money saves it for you.'))) where id = 'day-13' and strpos(data #>> '{tips,2}', 'Live key: same boxes ticked, the same two secrets, T212_ENV set to live.') > 0;
commit;
